import{_ as s,l as d,o as e,c as l,v as t,p as n,x as r,d as i,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"ALU 数据通路","description":"","frontmatter":{"title":"ALU 数据通路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alu-datapath.md","filePath":"cs/alu-datapath.md","lastUpdated":1789023840000}'),p={name:"cs/alu-datapath.md"};function h(u,a,_,U,E,B){const o=d("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="alu-数据通路" tabindex="-1">ALU 数据通路 <a class="header-anchor" href="#alu-数据通路" aria-label="Permalink to &quot;ALU 数据通路&quot;">​</a></h1><div class="epigraph"><p>ALU 不是「会算的云」，而是加法器、逻辑单元与若干 MUX 接在同一组操作数上，由操作码选出哪一路成为结果。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p>上一课<a href="/cs/barrel-shifter">移位与桶形移位</a>钉死了加减组合块。本课不重推 \\(g,p\\)，也不从 ISA 操作码表另起。缺口是：CPU 还要与、或、异或、移位、置位。需要一条<strong>数据通路</strong>：操作数进入，功能块并行（或复用），MUX 选出结果，并给出零、负、溢出等旗标。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>加法器只有和。RISC-V 整数指令还要 <code>and</code>/<code>or</code>/<code>xor</code>/<code>slt</code>。缺口因此不是再造一种进位，而是把若干组合功能并在 A、B 上：逻辑按位、加减走加法器、比较可借减法的符号与溢出。<code>ALUOp</code> 控制内部 MUX 与加法器的 \\(c_0\\)、B 反相。本课只钉这条通路；哪条指令产生哪组控制，是<a href="/cs/control-truth-table">控制器真值表</a>。</p><p>移位可以是桶形移位器（MUX 树），延迟另计。本课承认移位是 ALU 家族，不把 \\(n\\) 位桶形的每一级画出。</p><h3 id="alu-不是微程序仓库" tabindex="-1">ALU 不是微程序仓库 <a class="header-anchor" href="#alu-不是微程序仓库" aria-label="Permalink to &quot;ALU 不是微程序仓库&quot;">​</a></h3><p>本课的 ALU 是组合：输入稳定后 \\(t_{pd}\\) 内出结果。没有内部逐步微操作。多周期里 ALU 被多次使用，仍是同一组合块加寄存器在外——那是后课。把 ALU 当成「一台小 CPU」，会与存储程序混层。</p><p><span class="marginnote">Harris 与 Patterson/Hennessy 都把 ALU 画成带 ALUControl 的框。<code>slt</code> 用减法后看负异或溢出，把比较并进算术通路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>A、B 入。B 经 MUX 选原值或 \\(\\bar B\\)。加法器算 \\(A+B_{\\mathrm{sel}}+c_0\\)。逻辑单元算 \\(A\\land B\\) 等。结果 MUX 按 <code>ALUControl</code> 选。零旗标是结果各位或非。</p>',11)),(e(),n(A,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AB%5B%22%E6%93%8D%E4%BD%9C%E6%95%B0%20A%2C%20B%22%5D%20--%3E%20LOG%5B%22%E6%8C%89%E4%BD%8D%E9%80%BB%E8%BE%91%22%5D%0A%20%20AB%20--%3E%20ADD%5B%22%E5%8A%A0%E5%87%8F%20CLA%22%5D%0A%20%20ADD%20--%3E%20MUX%5B%22%E7%BB%93%E6%9E%9C%20MUX%22%5D%0A%20%20LOG%20--%3E%20MUX%0A%20%20MUX%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%AF%94%E8%BE%83%E5%99%A8%E7%BB%86%E5%8C%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课寄存器堆的两个读口接到 A、B；写口接结果（或更后的 MemtoReg）。关键路径包含 ALU 的 \\(t_{pd}\\)。<code>sub</code> 与 <code>beq</code> 都可能用减法：零旗标给相等。本课不接 PC 与立即数——那是单周期数据通路把 ALUSrc 再加一层 MUX。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现除法、不把浮点 FPU 画进同一框。乘法可视为后课独立单元。比较器下一课可以强调无加减的幅度比较；本课已允许用减法实现 <code>slt</code>。</p><p>后课默认：整数 ALU 是组合，功能由一小组控制位选择；加减共用 CLA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ALU = 算术块 + 逻辑块 + 结果选择。</li><li>控制位来自后课译码，本课只留端口。</li><li>仍是组合，延迟计入 CPU 关键路径。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD (RISC-V)。</li></ul>',7))])}const L=s(p,[["render",h]]);export{C as __pageData,L as default};
